import { createGlobalStyle } from 'styled-components';

const GlobalStyles = createGlobalStyle`
  :root {
    --primary-color: #4CAF50; /* A vibrant green */
    --secondary-color: #FFC107; /* A warm yellow */
    --background-color: #F0F4F8; /* A light, neutral background */
    --text-color: #333; /* Dark gray for text */
    --text-light: #666; /* Lighter gray for secondary text */
    --font-primary: 'Poppins', sans-serif;
    --font-secondary: 'Montserrat', sans-serif;
    --spacing-unit: 1rem; /* Base spacing unit */
    --border-radius: 8px; /* Rounded corners */
    --box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1); /* Subtle shadow */
    --transition: all 0.3s ease; /* Smooth transitions */
  }

  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    font-family: var(--font-primary);
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--background-color);
    transition: var(--transition);
  }

  a {
    text-decoration: none;
    color: var(--primary-color);
    transition: var(--transition);

    &:hover {
      color: var(--secondary-color);
    }
  }

  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-secondary);
    font-weight: 600;
    margin-bottom: var(--spacing-unit);
    color: var(--text-color);
  }

  p {
    margin-bottom: var(--spacing-unit);
    color: var(--text-light);
  }

  img {
    max-width: 100%;
    height: auto;
    border-radius: var(--border-radius);
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-unit);
  }

  button {
    background-color: var(--primary-color);
    color: white;
    border: none;
    padding: calc(var(--spacing-unit) * 0.75) var(--spacing-unit);
    border-radius: var(--border-radius);
    cursor: pointer;
    transition: var(--transition);
    box-shadow: var(--box-shadow);

    &:hover {
      background-color: var(--secondary-color);
      transform: translateY(-2px);
    }
  }

  .card {
    background: white;
    padding: var(--spacing-unit);
    border-radius: var(--border-radius);
    box-shadow: var(--box-shadow);
    transition: var(--transition);

    &:hover {
      transform: translateY(-5px);
      box-shadow: 0 6px 12px rgba(0, 0, 0, 0.15);
    }
  }
`;

export default GlobalStyles;
